// CSD_RATIONALE_BEGIN
// Attempt 68 (7.3%) regressed catastrophically because:
//   (1) The guidance was changed from the proven "Output SQL: <<query>>" format
//       hint to a longer instruction without the <<>> format cue. The 4B model
//       lost the signal for where to place constrained output, causing the
//       ConstrainedStep loop to receive stale/incorrect conditioned logits and
//       return EOS almost immediately on every step (avg 10 tokens/example,
//       252 ConstrainedStep calls/example, only ~10 AppendConstrainedToken/example).
//   (2) Removing the IsCompletePrefix early break had no structural benefit here
//       since the EOS issue dominated.
//
// Reverting to attempt 66 (53.3%, best) as base. The primary remaining failure
// mode is 138/300 semantic mismatches: syntactically valid SQL but wrong
// tables/columns/conditions. The RegenerateUnitOnGroundingFailure helper is
// the right tool for this but was configured conservatively (maxRetries=5,
// maxRollbackBudget=50).
//
// Single targeted change: increase maxRetries 5→8 and maxRollbackBudget 50→70
// in RegenerateUnitOnGroundingFailure. More retries per schema-symbol boundary
// means the grounding mechanism can reject wrong identifiers more aggressively
// before accepting them. Wider rollback budget lets it search deeper in the
// prefix for a clean restart point. All other parameters unchanged from attempt 66.
//
// Phase 1: ≤5 unconstrained steps (preamble, lets model emit "SQL: <<" naturally)
// Phase 2: Force OpenConstrainedSpan if not already inside
// Phase 3: RegenerateUnitOnGroundingFailure(budget=min(remaining-1,300), maxRetries=8, maxRollbackBudget=70)
// Phase 4a: CloseConstrainedSpan if IsCompletePrefix
// Phase 4b: CloseSpanWithinBudget(120) if not yet complete
// Guidance: identical to attempt 66 (proven best, no changes)
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble loop: Loop guard requires !insideConstrainedOut, so the
//   implication is vacuous on every iteration. The only flip to true happens
//   via RenderedEndsWith, at which point we set currentConstrainedOut := []
//   and parser.IsValidPrefix([]) holds by method precondition. EOS break
//   leaves insideConstrainedOut false (implication vacuous).
//
// Phase 2 OpenConstrainedSpan: Runs only when !insideConstrainedOut. Its
//   postcondition sets currentConstrainedOut := []; IsValidPrefix([]) holds.
//
// Phase 3 RegenerateUnitOnGroundingFailure: Its postcondition guarantees
//   parser.IsValidPrefix(resultConstrained) always. We assign
//   currentConstrainedOut := resultConstrained, re-establishing the invariant.
//   insideConstrainedOut remains true (unchanged from Phase 2 or entry).
//
// Phase 4a CloseConstrainedSpan: Sets insideConstrainedOut := false, making
//   the implication vacuously true; sets currentConstrainedOut := [].
// Phase 4b CloseSpanWithinBudget: Its postcondition directly guarantees
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep costs +1 step; appends 0 (EOS) or 1 (non-EOS)
//   token per iteration. steps increments by 1 and |generated| by at most 1.
//   Invariant preserved each iteration.
//
// Phase 2: OpenConstrainedSpan costs +1 step, appends exactly 1 "<<" token.
//   steps +1, |generated| +1: invariant preserved.
//
// Phase 3: Let old_steps = steps before Phase 3, old_gen = generated before
//   Phase 3, old_cc = currentConstrainedOut before Phase 3.
//   stablePrefix = old_gen[..|old_gen| - |old_cc|], so |stablePrefix| =
//   |old_gen| - |old_cc|. Helper cost postcondition: "at most +budget" means
//   each step produces at most one visible token, so |resultConstrained| <=
//   sqlBudget. Then:
//   |new generated| = |stablePrefix| + |resultConstrained|
//     = (|old_gen| - |old_cc|) + |resultConstrained|
//     <= |old_gen| + sqlBudget   (since |resultConstrained| <= sqlBudget and |old_cc| >= 0)
//     <= |generatedPrefix| + old_steps + sqlBudget
//     = |generatedPrefix| + new_steps.
//   sqlBudget <= remaining - 1 = maxSteps - old_steps - 1 ensures
//   new_steps = old_steps + sqlBudget <= maxSteps - 1 < maxSteps.
//
// Phase 4a: CloseConstrainedSpan costs +1 step, appends at most 1 ">>" token.
//   steps +1, |generated| +0 or +1: invariant preserved.
// Phase 4b: CloseSpanWithinBudget postcondition: |generatedOut| <= |generated|
//   + closeBudget; steps += closeBudget. Invariant preserved by transitivity.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a valid SQL SELECT statement using ONLY the exact table and column names from the provided schema. The SQL must be placed between << and >>. No explanation, no markdown, no aliases not in the schema.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 5 steps) to let model emit "SQL: <<" naturally
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Schema-grounded SQL via RegenerateUnitOnGroundingFailure
// Budget capped at 300 to avoid runtime timeout (2.10s/token, 600s limit).
// maxRetries raised 5→8 and maxRollbackBudget raised 50→70 to more aggressively
// reject wrong schema identifiers at each table/column symbol boundary.
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  if remaining >= 2 {
    var sqlBudget: nat;
    if remaining - 1 <= 300 {
      sqlBudget := remaining - 1;
    } else {
      sqlBudget := 300;
    }
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var resultConstrained := helpers.RegenerateUnitOnGroundingFailure(
      lm, parser, constrainedPrompt, currentConstrainedOut, eosToken, sqlBudget, 8, 70
    );
    var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
    generated := stablePrefix + resultConstrained;
    currentConstrainedOut := resultConstrained;
    steps := steps + sqlBudget;
  }
}

// Phase 4: Close the constrained span
if insideConstrainedOut && steps < maxSteps {
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    var remaining := maxSteps - steps;
    var closeBudget: nat;
    if remaining <= 120 {
      closeBudget := remaining;
    } else {
      closeBudget := 120;
    }
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + closeBudget;
  }
}

cost := steps;

